  "kiosk-posm-44": {"descriptionVi":"Backdrop check-in hội nghị in tranh sông nước, khung nan tre hắt LED, bảng tròn gỗ Check-in và tiểu cảnh xuồng, cây xanh trong sảnh khách sạn.","descriptionEn":"Conference check-in backdrop with a printed river scene, LED-backlit bamboo slat frame, round timber Check-in sign and a boat-and-plant display in a hotel lobby.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-44-imagegen-20261018.webp","sha256":"3a5df73f39ce8e916a56f0d55cff6e85a246390875cc45616a73a5a67aa777ff","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-check-in-1; original SHA256 cdfb63b2d44bc86863bd024c7450e2c19bd11da0d5c1cf4d5cc5b4a49c13d248."},
  "kiosk-posm-45": {"descriptionVi":"Gian hàng hội chợ đặc sản khung gỗ nan, backdrop in tranh sông nước, kệ trưng bày và quầy tròn hắt LED chân trong nhà triển lãm.","descriptionEn":"Trade fair booth for regional specialties with a slatted timber frame, printed river-scene backdrop, display shelving and a round counter with an LED-lit base in an exhibition hall.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-45-imagegen-20261018.webp","sha256":"6db6338ebb2e73fff786558607b26a9591561e1f20e4e09fa28e09a64135adc9","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-hoi-cho-1; original SHA256 27695eaca8b91beb5f71f43d3d348648dd7c1e49d1909249431697cce380f393."},
  "kiosk-posm-46": {"descriptionVi":"Backdrop sân khấu hội nghị in tranh vườn dừa, tấm cắt CNC hình lá viền LED hắt sáng, ốp nan gỗ hai bên trong phòng hội nghị khách sạn.","descriptionEn":"Conference stage backdrop printed with a coconut grove scene, CNC-cut leaf panels with LED edge lighting and timber slat side panels in a hotel ballroom.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-46-imagegen-20261018.webp","sha256":"a22e3d4a27c9be069ca6bbbf8b6f9b87b1ef432e193093133f9803b5db515d24","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-hoi-nghi-1; original SHA256 6afa6447a8fe463d30ba6121c57c00667e5b3a2caa08ff1721f12e9f7f94bd84."},
  "kiosk-posm-47": {"descriptionVi":"Backdrop khai trương hình hoa sen nhiều lớp cánh cắt CNC hắt LED, chữ nổi tên cửa hàng, đặt trên thảm hồng trước cửa hàng mỹ phẩm.","descriptionEn":"Grand-opening backdrop shaped as a layered lotus with CNC-cut LED-backlit petals and raised store lettering, set on a pink carpet outside a cosmetics shop.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-47-imagegen-20261018.webp","sha256":"60c5300aa79daa2eedc2585c00b368d50e08b8ea414c5f658d23a325c800dd9e","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-khai-truong-1; original SHA256 45ae2aada72fb7cb2f4ef319b9141e54d8f0319580515abf96d7a17517a4bbee."},
  "kiosk-posm-48": {"descriptionVi":"Backdrop tường nhà hàng chạm nổi phong cảnh sông nước, chữ nổi hắt sáng LED, khung tre và đèn LED viền chân trong nhà hàng ven sông.","descriptionEn":"Restaurant feature-wall backdrop with a relief river landscape, LED halo-lit raised lettering, bamboo framing and LED base lighting in a riverside restaurant.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-48-imagegen-20261018.webp","sha256":"2cf84a3d75b19b35c54e0403b6654d0dc6aa80b75eac001b7c1798a86e7db272","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-nha-hang-1; original SHA256 c15b3214f07c019e12d42e10e7163a23ba718fe5ff23082a638fcbb4150e5833."},
  "kiosk-posm-49": {"descriptionVi":"Backdrop showroom vòm phù điêu sóng và hàng dừa, chữ nổi tên thương hiệu, ốp nan gỗ và hốc kệ hắt LED sau quầy cửa hàng sản phẩm từ dừa.","descriptionEn":"Showroom backdrop with an arched relief of waves and palms, raised brand lettering, timber slat cladding and LED-lit shelf niches behind the counter of a coconut-products store.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-49-imagegen-20261018.webp","sha256":"d13fcfacaa65e4fd93cbde259417ad5ee029553acc75845fa8708e4e4596d609","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-showroom-1; original SHA256 c0940bdb6e2902e67bb76fc283bc1a748fc090dd3192f6fd05a136ab01c66dc3."},
  "kiosk-posm-50": {"descriptionVi":"Cổng backdrop tiệc cưới lễ Vu Quy bằng tấm cắt CNC sơn trắng và cam, viền LED hắt sáng, hoa tươi và đèn lồng mây trước rạp cưới ngoài trời.","descriptionEn":"Wedding entrance backdrop of CNC-cut panels painted white and orange with LED edge lighting, fresh flowers and rattan lanterns at an outdoor wedding marquee.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-50-imagegen-20261018.webp","sha256":"7f6be1f3bd7ad3aa64b3ad9441af8e309d9e55d7433ead3999b61b47d358a5d3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-tiec-cuoi-1; original SHA256 051a176c907bcfe697b03e8d62d52330aecd3845ac7407c6948cc49483d3e06c."},
  "kiosk-posm-51": {"descriptionVi":"Backdrop sân khấu lễ khai giảng in bạt tranh hoa sen và cầu dây văng, cánh gà tấm cắt đỏ vàng, sân khấu trải thảm đỏ ngoài sân trường.","descriptionEn":"School opening-ceremony stage backdrop printed with lotus flowers and a cable-stayed bridge, red and gold cut-panel wings and a red-carpeted stage in a schoolyard.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-51-imagegen-20261018.webp","sha256":"0d97b9e048f1c27af2fa866b00e665f9413aa80dd901cf806a3cda69a8d8bd09","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-truong-hoc-1; original SHA256 27631961cb876fb64020bf5d57e10d3dab5c502d3f64695460674efd70f97e19."},
  "kiosk-posm-52": {"descriptionVi":"Backdrop quầy lễ tân văn phòng giao dịch với logo và chữ nổi hắt sáng LED, tường cong ốp nan gỗ, quầy đá viền LED chân.","descriptionEn":"Reception backdrop for a branch office with an LED halo-lit logo and raised lettering on a curved timber-slat wall behind a stone-finish counter with LED base lighting.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-52-imagegen-20261018.webp","sha256":"a9eb16eb105755d2fe7aecea8275e845f132528fd340028311e4d865df5e4da2","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:bd-van-phong-1; original SHA256 8648ad8a7b60e75996aa5ffb7058fd58c7d0b75b3cc9051db7fd211e49c9f7c2."},
  "kiosk-posm-53": {"descriptionVi":"Gian hàng hội chợ đặc sản miền Tây khung tre mái lá, bảng gỗ, banner đứng và kệ tre trưng bày sản phẩm.","descriptionEn":"Trade fair booth for Mekong Delta specialties with a bamboo frame, thatched roof, timber signboard, roll-up banner and bamboo display shelves.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-53-imagegen-20261018.webp","sha256":"0f21ebacf146aa2c52405fd26803284fd20801593012363dec337c339f684018","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:gian-trien-lam-bu-01-1; original SHA256 df88cc879b0cc89120eabebef315e47b80d0bdf9dd2d740c577adb37cc1696da."},
