  "kiosk-posm-55": {"descriptionVi":"Xe kiosk nước dừa bằng gỗ có mái tôn, bảng hiệu chữ nổi phát sáng và mặt quầy in hình dừa, đặt trên phố đi bộ ven sông.","descriptionEn":"Timber coconut drink cart kiosk with a metal canopy, illuminated raised-letter sign and coconut-printed counter front, on a riverside promenade.","source":"/assets/content/projects/advertising/kiosk-posm/kiosk-posm-55-imagegen-20261018.webp","sha256":"1b23e6d9d057edbe14a29cd92e15ceaa257909275e3e7e84bf955b905467d510","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:kiosk-bu-02-1; original SHA256 ea08cdab839259dbe3136df03ce72ca140598ee86256f5b8fcee6efd169980fd."},
  "led-displays-lightboxes-31": {"descriptionVi":"Bảng hiệu trang trí trong quán chay: tấm gỗ cắt hình mây in hoa sen, viền và chữ LED neon trên vách lam gỗ.","descriptionEn":"Decorative sign in a vegetarian restaurant: a cloud-shaped timber panel printed with lotus flowers, with LED neon outline and lettering on a slatted wood wall.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-31-imagegen-20261018.webp","sha256":"eab95dcdefaf09e1573245d4840aba65937e8f9d3f53f09cc88fe1f6bd1f3095","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-01-1; original SHA256 470b3dd795e65f747463be1585933dd1adfd6e362530d2012bb647b81a38791a."},
  "led-displays-lightboxes-32": {"descriptionVi":"Hộp đèn vẫy viền gỗ cắt hình hoa văn treo trên giá thép trước quán trà, cà phê ven sông lúc chạng vạng.","descriptionEn":"Shaped lightbox projecting sign with a timber rim hung from a steel bracket at a riverside tea and coffee shop at dusk.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-32-imagegen-20261018.webp","sha256":"bcf923e32ce3ff6b94d512c6ce73239a938be7fb5fa7a4f41e494210102d82a3","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-01-2; original SHA256 1f54b5a1e2463fdd33c83e50455ef353206b6e6e0316311da412cbcf91dfd569."},
  "led-displays-lightboxes-33": {"descriptionVi":"Cổng vòm tre trang trí hoa sen và lá sen viền LED neon, bảng gỗ chữ phát sáng, trước quán ăn ven sông về đêm.","descriptionEn":"Bamboo entrance arch decorated with lotus flowers and leaves outlined in LED neon, with an illuminated timber sign, at a riverside restaurant at night.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-33-imagegen-20261018.webp","sha256":"a7868f80d7d0f81f2f6b7b3095d44c813be68d0743e564df962af09b8d1cd0e8","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-decor-bu-02-1; original SHA256 9fb7761425e6b9d59e076cbd83686cdef3e3c6f3082f2a04e5226bf0c5d279fc."},
  "led-displays-lightboxes-34": {"descriptionVi":"Bảng vẫy LED quán cơm bún treo trên giá thép, chữ Cơm và hình tô bún bằng LED neon, chữ BÚN bằng LED điểm, viền LED điểm.","descriptionEn":"Projecting LED sign for a rice and noodle eatery hung from a steel bracket, with LED neon script and noodle-bowl graphic, point-LED lettering and a point-LED border.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-34-owner-20261019.webp","sha256":"c7996fe720842b5f72e53fa1f81b4dd7c38f06f106c0739848e5a0fa18e781e2","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-02-2; original SHA256 1ef91a76c0ff47d6e282b02b199a4c43e21ed4e6b73db3ba4eb9fd3e313200b1."},
  "led-displays-lightboxes-35": {"descriptionVi":"Bảng vẫy LED điểm nhận gửi hàng gắn giá sắt bên hiên nhà phố, chữ LED điểm trắng và vàng, viền LED điểm xanh lá.","descriptionEn":"Projecting point-LED sign for a parcel drop-off point on an iron bracket beside a shophouse, with white and amber point-LED lettering and a green point-LED border.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-35-owner-20261019.webp","sha256":"e0d72d5c2e58b2cd714d9cc3223d62c03d66d56309d05471aeb007f1aea15ce5","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-03-1; original SHA256 ff146b57259bc04f9e5cfb86757c979eacd4f6039e92e13239699850b572449f."},
  "led-displays-lightboxes-36": {"descriptionVi":"Bảng vẫy LED tiệm chụp ảnh in ảnh thẻ, chữ LED điểm đỏ và vàng, biểu tượng máy ảnh LED neon, viền LED điểm xanh dương, treo trên khung sắt trước cửa tiệm.","descriptionEn":"Projecting LED sign for a photo and ID-print shop with red and amber point-LED lettering, an LED neon camera icon and a blue point-LED border, hung from an iron frame at the shopfront.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-36-owner-20261019.webp","sha256":"7d4365bcc37478d7f2dcd4309badc688d38e64b21c6ab4d5c073b558453bce9c","provenance":"AI-generated illustration edited by the owner; source ID owner-edit:2026-10-19:led-sign-04-1; original SHA256 256c99a55c1f50aa42f81b058a5ff612ba69966032dbc33aebbaa78a4a923711."},
  "led-displays-lightboxes-37": {"descriptionVi":"Bảng vẫy LED neon tiệm trang điểm cô dâu, chữ và viền LED neon, hình cô dâu in UV trên mica, treo trên khung sắt trước tiệm áo cưới.","descriptionEn":"Projecting LED neon sign for a bridal makeup studio with LED neon lettering and border and a UV-printed acrylic bride illustration, hung from an iron frame outside a bridal shop.","source":"/assets/content/projects/advertising/led-displays-lightboxes/led-displays-lightboxes-37-imagegen-20261018.webp","sha256":"5c6dd36dd691ccee21b27e65dcba5923dd787db3c183aafb0038ea036753e360","provenance":"AI-generated illustration; source ID imagegen:2026-10-18:led-sign-05-2; original SHA256 d281034870c5d464690b341ce2251afd46e797bde538346db0e6ef52f9b75f23."},
